body:
- added `client-gen` to make
- added autogenerated client pkg

Fixes #24 

Example Usage:

```go
package main

import (
	"context"
	"fmt"
	"log"
	"os"

	tfv1alpha1 "github.com/isaaguilar/terraform-operator/pkg/client/clientset/versioned/typed/tf/v1alpha1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/tools/clientcmd"
)

func main() {
	kubeconfig := os.Getenv("KUBECONFIG")
	config, err := clientcmd.BuildConfigFromFlags("", kubeconfig)
	if err != nil {
		panic(err)
	}

	clientset, err := tfv1alpha1.NewForConfig(config)
	if err != nil {
		log.Panic(err)
	}

	tfs, err := clientset.Terraforms("").List(context.TODO(), metav1.ListOptions{})
	if err != nil {
		log.Panic(err)
	}

	for _, item := range tfs.Items {
		fmt.Println(item.Name)
	}
}
```

